:root {
  --bg: #0d1b2a;
  --bg-2: #1b2838;
  --surface: #132233;
  --surface-2: #1a3148;
  --text: #e8f1fb;
  --muted: #a9bbcf;
  --accent: #00b4d8;
  --accent-2: #0077b6;
  --ok: #6cc24a;
  --danger: #ff6b6b;
  --border: #2a4058;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif; background: linear-gradient(180deg, var(--bg), #0a1624 60%); color: var(--text); }
a { color: inherit; text-decoration: none; }
.container { width: min(1120px, calc(100% - 2rem)); margin: 0 auto; }
.header { position: sticky; top: 0; z-index: 20; backdrop-filter: blur(10px); background: rgba(13,27,42,.92); border-bottom: 1px solid var(--border); }
.nav { display: flex; align-items: center; justify-content: space-between; padding: .9rem 0; gap: 1rem; }
.brand { font-weight: 700; letter-spacing: .2px; }
.nav-links { display: flex; gap: 1rem; align-items: center; flex-wrap: wrap; }
.nav-link, .drop-btn { padding: .5rem .75rem; border-radius: 8px; color: var(--muted); border: 1px solid transparent; background: transparent; cursor: pointer; font: inherit; }
.nav-link:hover, .drop-btn:hover { color: var(--text); border-color: var(--border); }
.dropdown { position: relative; }
.dropdown-menu { position: absolute; top: 120%; left: 0; min-width: 220px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; box-shadow: var(--shadow); display: none; overflow: hidden; }
.dropdown.open .dropdown-menu { display: block; }
.dropdown-menu a { display: block; padding: .65rem .8rem; color: var(--muted); }
.dropdown-menu a:hover { background: rgba(0,180,216,.1); color: var(--text); }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: .5rem; padding: .75rem 1rem; border-radius: 10px; border: 1px solid transparent; font-weight: 600; cursor: pointer; }
.btn-primary { background: linear-gradient(135deg, var(--accent), var(--accent-2)); color: #06111b; }
.btn-primary:hover { filter: brightness(1.08); }
.btn-secondary { border-color: var(--border); color: var(--text); background: transparent; }
main { padding-bottom: 4rem; }
.hero { padding: 4rem 0 3rem; }
.eyebrow { color: var(--accent); text-transform: uppercase; letter-spacing: .12em; font-size: .78rem; font-weight: 700; }
h1 { font-size: clamp(2rem, 4vw, 3.2rem); line-height: 1.1; margin: .75rem 0 1rem; }
.lead { color: var(--muted); max-width: 70ch; line-height: 1.6; }
.actions { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 1.4rem; }
.section { padding: 2.5rem 0; }
.section h2 { font-size: clamp(1.45rem, 2.5vw, 2rem); margin: 0 0 .6rem; }
.grid { display: grid; gap: 1rem; }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.card { background: linear-gradient(180deg, rgba(26,49,72,.9), rgba(19,34,51,.9)); border: 1px solid var(--border); border-radius: 14px; padding: 1rem; box-shadow: var(--shadow); }
.card h3 { margin: .2rem 0 .5rem; font-size: 1.05rem; }
.card p, li { color: var(--muted); line-height: 1.55; }
.tabs { display: flex; gap: .5rem; flex-wrap: wrap; margin: 1rem 0; }
.tab-btn { padding: .6rem .8rem; border-radius: 8px; border: 1px solid var(--border); background: transparent; color: var(--muted); cursor: pointer; }
.tab-btn[aria-selected="true"] { color: var(--text); border-color: var(--accent); background: rgba(0,180,216,.12); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-trigger { width: 100%; background: transparent; color: var(--text); border: 0; padding: .9rem 0; text-align: left; display: flex; justify-content: space-between; cursor: pointer; font-size: 1rem; }
.accordion-content { display: none; padding-bottom: .9rem; color: var(--muted); }
.accordion-item.open .accordion-content { display: block; }
.stat-circle { aspect-ratio: 1/1; border-radius: 50%; border: 3px solid var(--accent); display: grid; place-items: center; text-align: center; padding: 1rem; background: radial-gradient(circle at top, rgba(0,180,216,.18), transparent 60%); }
.stat-circle .big { font-size: 2rem; font-weight: 800; color: #e8f7ff; }
.progress-track { width: 100%; height: 8px; background: #102131; border-radius: 999px; overflow: hidden; border: 1px solid var(--border); }
.progress-bar { height: 100%; background: linear-gradient(90deg, var(--accent), var(--ok)); }
.diagram { background: #0f2235; border: 1px solid var(--border); border-radius: 16px; padding: 1rem; }
.carousel-dots { display: flex; gap: .5rem; justify-content: center; margin-top: .75rem; }
.dot { width: 10px; height: 10px; border-radius: 50%; border: 0; background: #2e4d67; cursor: pointer; }
.dot.active { background: var(--accent); }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: .8rem; }
label { display: block; margin: .45rem 0; font-size: .92rem; }
input, select, textarea { width: 100%; padding: .72rem .78rem; border-radius: 8px; border: 1px solid var(--border); background: #102131; color: var(--text); }
small.error { color: var(--danger); display: none; }
small.error.show { display: block; }
.cookie-banner { position: fixed; inset: auto 1rem 1rem 1rem; z-index: 30; background: rgba(12,26,39,.98); border: 1px solid var(--border); border-radius: 12px; padding: .9rem; box-shadow: var(--shadow); display: none; }
.cookie-banner.show { display: block; }
.footer { border-top: 1px solid var(--border); color: var(--muted); padding: 1.5rem 0; margin-top: 2rem; }
@media (max-width: 900px) { .grid-3 { grid-template-columns: 1fr 1fr; } .form-row { grid-template-columns: 1fr; } }
@media (max-width: 680px) { .grid-2, .grid-3 { grid-template-columns: 1fr; } .nav { align-items: flex-start; } .nav-links { width: 100%; } }
